import React from 'react';

import clsx from 'clsx';

import { dateRangeToLocaleString } from '@helpers/dateHelper';
import { formatDistance } from '@helpers/formatHelper';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { IHikingGpx } from '../../../@types/hiking.types';

interface IHikingTrackListItemProps {
  hikingGpxTrack: IHikingGpx;
  toolbar?: React.ReactNode;
}

const Metric = ({
  value,
  label,
  textClass = 'text-muted',
  valueClass = 'text-success',
}: {
  value: React.ReactNode;
  label: React.ReactNode;
  textClass?: string;
  valueClass?: string;
}) => {
  return (
    <span className="d-inline-block">
      <strong className={valueClass}>{value}</strong>
      <small className={clsx('d-block mt-n2', textClass)}>{label}</small>
    </span>
  );
};

const MetricGroup = ({
  label,
  children,
  textClass = 'text-muted',
}: {
  children: React.ReactNode;
  label: React.ReactNode;
  textClass?: string;
}) => {
  return (
    <span className="d-inline-block p-0 text-start">
      <small className={textClass}>{label}</small>
      <small className={clsx('d-flex mt-n1')} style={{ gap: 8 }}>
        {children}
      </small>
    </span>
  );
};

const HikingTrackListItem: React.FC<IHikingTrackListItemProps> = ({ hikingGpxTrack, toolbar }) => {
  let mainBlockSize = 7;
  if (toolbar) {
    mainBlockSize = 6;
  }
  return (
    <PohRow className="m-n2" title={`Загружено ${hikingGpxTrack.dateCreate.toLocaleString()}`}>
      <PohCol sm={mainBlockSize}>
        <strong className="d-block">
          <PohBadge variant={BadgeVariant.Success} className="float-end mt-1">
            {formatDistance(hikingGpxTrack.distance)}
          </PohBadge>
          {hikingGpxTrack.name}
        </strong>
        <small className="text-muted">
          {dateRangeToLocaleString(hikingGpxTrack.start, hikingGpxTrack.finish)},{' '}
          <strong className="text-success">
            продолж:{' '}
            {new Date(
              hikingGpxTrack.timeMoving * 1000 + new Date().getTimezoneOffset() * 60000,
            ).toLocaleTimeString('default', { timeStyle: 'short' })}
          </strong>
        </small>
      </PohCol>
      <PohCol sm={5} className="d-flex" style={{ gap: 12 }}>
        <MetricGroup label="Высота, м">
          <Metric label="макс." value={hikingGpxTrack.altitude.max} />
          <Metric label="мин." value={hikingGpxTrack.altitude.min} />
          <Metric label="набор" value={hikingGpxTrack.altitude.ascent} />
          <Metric label="сброс" value={hikingGpxTrack.altitude.descent} />
        </MetricGroup>
        <MetricGroup label="Скорость, км/ч">
          <Metric label="ср.общ" value={hikingGpxTrack.speed.avg} />
          <Metric label="макс" value={hikingGpxTrack.speed.max} />
          <Metric label="мин" value={hikingGpxTrack.speed.min} />
        </MetricGroup>
      </PohCol>

      {toolbar && (
        <PohCol as="aside" sm={1} className="d-flex justify-content-end" style={{ gap: 8 }}>
          {toolbar}
        </PohCol>
      )}
    </PohRow>
  );
};

export default HikingTrackListItem;
